{
  "title": "Робота Redis Test",
  "description": "Квіз про структури даних та механізми роботи Redis.",
  "questions": [
    {
      "title": "Які структури даних підтримує Redis?",
      "allows_multiple_correct": true,
      "options": [
        {
          "text": "String",
          "is_correct": true
        },
        {
          "text": "Hash",
          "is_correct": true
        },
        {
          "text": "List",
          "is_correct": true
        },
        {
          "text": "Relational Table",
          "is_correct": false
        }
      ]
    },
    {
      "title": "Які механізми збереження даних підтримує Redis?",
      "allows_multiple_correct": true,
      "options": [
        {
          "text": "RDB snapshots",
          "is_correct": true
        },
        {
          "text": "AOF (Append Only File)",
          "is_correct": true
        },
        {
          "text": "WAL сегменти PostgreSQL",
          "is_correct": false
        },
        {
          "text": "Hybrid persistence",
          "is_correct": true
        }
      ]
    },
    {
      "title": "Які можливості кластеризації має Redis?",
      "allows_multiple_correct": true,
      "options": [
        {
          "text": "Redis Cluster",
          "is_correct": true
        },
        {
          "text": "Replication (master-replica)",
          "is_correct": true
        },
        {
          "text": "Sharding через cluster slots",
          "is_correct": true
        },
        {
          "text": "Built-in SQL joins",
          "is_correct": false
        }
      ]
    },
    {
      "title": "Для чого найчастіше використовується Redis?",
      "allows_multiple_correct": true,
      "options": [
        {
          "text": "Кешування",
          "is_correct": true
        },
        {
          "text": "Pub/Sub повідомлення",
          "is_correct": true
        },
        {
          "text": "Черги завдань",
          "is_correct": true
        },
        {
          "text": "OLAP-аналітика великих даних",
          "is_correct": false
        }
      ]
    },
    {
      "title": "Які особливості продуктивності Redis?",
      "allows_multiple_correct": true,
      "options": [
        {
          "text": "In-memory зберігання",
          "is_correct": true
        },
        {
          "text": "Однопотокова модель обробки команд",
          "is_correct": true
        },
        {
          "text": "Використання JVM для кожного запиту",
          "is_correct": false
        },
        {
          "text": "Мінімальні затримки (low latency)",
          "is_correct": true
        }
      ]
    }
  ]
}

